# Build a set of (title, artist) for old songs
old_song_keys = set()
for song in old_songs:
    for artist in song["artists"]:
        old_song_keys.add((song["title"].strip().lower(), artist.strip().lower()))

# Build a mapping from song_id to (title, artist) for all playlist songs
song_id_to_key = {}
for song_id, info in song_id_to_info.items():
    for artist in info["artists"]:
        key = (info["title"].strip().lower(), artist["name"].strip().lower())
        song_id_to_key[song_id] = key

# For each playlist, find song_ids to remove (those matching old songs)
playlist_songs_to_remove = {}
for playlist in all_playlists:
    to_remove = []
    for song_id in playlist["song_ids"]:
        key = song_id_to_key.get(song_id)
        if key and key in old_song_keys:
            to_remove.append(song_id)
    if to_remove:
        playlist_songs_to_remove[playlist["playlist_id"]] = to_remove

