steps.code:
# The "artist" field in old_songs is a string, sometimes with multiple artists separated by commas.
# Let's split the artist string on commas and strip whitespace for each.
# Then, build the set of (title, artist) pairs for matching.

old_song_keys = set()
for song in old_songs:
    artists = [a.strip().lower() for a in song["artist"].split(",")]
    for artist in artists:
        old_song_keys.add((song["title"].strip().lower(), artist))

# Now, build a mapping from song_id to all (title, artist) pairs for each song in the playlists.
song_id_to_keys = {}
for song_id, info in song_id_to_info.items():
    keys = []
    for artist in info["artists"]:
        keys.append((info["title"].strip().lower(), artist["name"].strip().lower()))
    song_id_to_keys[song_id] = keys

# For each playlist, find song_ids to remove (those matching old songs)
playlist_songs_to_remove = {}
for playlist in all_playlists:
    to_remove = []
    for song_id in playlist["song_ids"]:
        keys = song_id_to_keys.get(song_id, [])
        if any(key in old_song_keys for key in keys):
            to_remove.append(song_id)
    if to_remove:
        playlist_songs_to_remove[playlist["playlist_id"]] = to_remove

print(playlist_songs_to_remove)  # playlist_id -> list of song_ids to remove (and archive)

