# Let's collect all the old song Spotify IDs into a set for quick lookup.
old_song_ids = set([entry["spotify_song_id"] for entry in json_friendly_mapping])

# For each playlist, determine which old songs are present (i.e., which song_ids overlap).
# We'll build a mapping: playlist_id -> list of old song_ids to remove from that playlist.

playlist_songs_to_remove = {}
for playlist in all_playlists:
    to_remove = [song_id for song_id in playlist["song_ids"] if song_id in old_song_ids]
    if to_remove:
        playlist_songs_to_remove[playlist["playlist_id"]] = to_remove

print(playlist_songs_to_remove)

