steps.code:
# Now, let's remove all old songs (whose Spotify song IDs are in old_song_spotify_ids) from all playlists where they appear.
# The mapping playlist_old_songs is {playlist_id: [song_id, ...]} for playlists that contain old songs.
# We'll call remove_song_from_playlist for each (playlist_id, song_id) pair, skipping the new "Archived Songs" playlist.

for playlist_id, song_ids in playlist_old_songs.items():
    if int(playlist_id) == archived_playlist_id:
        continue  # Don't remove from the new archived playlist
    for song_id in song_ids:
        apis.spotify.remove_song_from_playlist(
            playlist_id=playlist_id,
            song_id=song_id,
            access_token=spotify_access_token
        )

