# Next, I need to check if a playlist named "Old Songs" already exists.
# If not, I will create it. If it exists, I will use its playlist_id.
# Let's check for "Old Songs" in the list of playlists.

old_songs_playlist = None
for playlist in all_playlists:
    if playlist["title"].strip().lower() == "old songs":
        old_songs_playlist = playlist
        break

if old_songs_playlist:
    old_songs_playlist_id = old_songs_playlist["playlist_id"]
else:
    old_songs_playlist_id = None

print(old_songs_playlist_id)  # None if not found, else the playlist_id

# The show_song API takes a song_id and returns details including title and artists.
# Let's fetch the metadata for all unique_song_ids so we can map them to the songs in the archive list.
# We'll build a mapping from (title.lower(), artist.lower()) to song_id for fast lookup.

song_id_to_metadata = {}
for song_id in unique_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    if isinstance(song, dict) and "title" in song and "artists" in song:
        # Use the first artist for mapping (assuming archive list is "Title - Artist")
        artist_name = song["artists"][0]["name"] if song["artists"] else ""
        song_id_to_metadata[song_id] = {
            "title": song["title"],
            "artist": artist_name
        }
print(song_id_to_metadata)

