steps.code:
# The archive list is in the format "Title by Artist".
# Let's parse these into (title.lower(), artist.lower()) pairs.
# Then, for each song in song_id_to_metadata, if its (title, artist) matches one in the archive set, collect its song_id.

archive_title_artist_set = set()
for entry in songs_to_archive:
    if " by " in entry:
        title, artist = entry.split(" by ", 1)
        archive_title_artist_set.add((title.strip().lower(), artist.strip().lower()))

# Build a mapping from (title.lower(), artist.lower()) to song_id
title_artist_to_song_id = {}
for song_id, meta in song_id_to_metadata.items():
    key = (meta["title"].strip().lower(), meta["artist"].strip().lower())
    title_artist_to_song_id[key] = int(song_id)

# Find song_ids to archive
archive_song_ids = []
for key in archive_title_artist_set:
    if key in title_artist_to_song_id:
        archive_song_ids.append(title_artist_to_song_id[key])

print(archive_song_ids)  # These are the Spotify song_ids to archive.

