steps.code:
# Let's proceed to remove the old songs from their respective playlists using the spotify_access_token.
# We'll call spotify.remove_song_from_playlist for each (playlist_id, song_id) pair.

remove_results = []
for playlist_id, song_ids in playlist_songs_to_remove.items():
    for song_id in song_ids:
        result = apis.spotify.remove_song_from_playlist(
            playlist_id=int(playlist_id),
            song_id=song_id,
            access_token=spotify_access_token
        )
        remove_results.append({
            "playlist_id": playlist_id,
            "song_id": song_id,
            "result": result
        })

print(remove_results)

