# The top result matches both the title "Tangled Lies" and artist "Ava Morgan".
# Let's extract the release month from the release_date "2022-12-11T06:22:44" (i.e., December 2022).
# We'll repeat this process for all entries in todo_entries and collect the release month for each.

from datetime import datetime

release_months = {}

for entry in todo_entries:
    query = f"{entry['song']} {entry['artists']}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the best match: title and all artists match
    found = None
    for song in results:
        if song['title'].lower() == entry['song'].lower():
            song_artists = set(a['name'].lower() for a in song['artists'])
            entry_artists = set(a.strip().lower() for a in entry['artists'].split(','))
            if song_artists == entry_artists:
                found = song
                break
    if not found and results:
        found = results[0]  # fallback to top result
    if found:
        dt = datetime.strptime(found['release_date'], "%Y-%m-%dT%H:%M:%S")
        release_months[entry['line']] = dt.strftime("%B %Y")
    else:
        release_months[entry['line']] = None

print(release_months)

