# Great! Now let's automate this for all songs in todo_songs.
# We'll search each song, match the best result (exact title and artist), and extract the release month.
# We'll collect a list of dicts: {title, artists, release_month}

release_months = []
for song in todo_songs:
    query = f"{song['title']} {' '.join(song['artists'])}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the best match: exact title and at least one matching artist
    match = None
    for r in results:
        if r["title"].lower() == song["title"].lower():
            result_artists = {a["name"].lower() for a in r["artists"]}
            song_artists = {a.lower() for a in song["artists"]}
            if result_artists & song_artists:
                match = r
                break
    if match:
        release_date = match["release_date"]
        release_month = datetime.fromisoformat(release_date).strftime("%B %Y")
    else:
        release_month = None
    release_months.append({
        "title": song["title"],
        "artists": song["artists"],
        "release_month": release_month
    })

print(release_months)

