steps.code:
# Great, we can extract the release month in the required format.
# Let's automate this for all songs in todo_songs: search each song, get the best match, and extract the release month.
# We'll collect a mapping of (title, artist) -> release_month.

release_months = {}
for song in todo_songs:
    query = f"{song['title']} {song['artists'][0]}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the first result that matches both title and artist exactly
    match = None
    for result in results:
        if (
            result["title"].lower() == song["title"].lower()
            and any(a["name"].lower() == song["artists"][0].lower() for a in result["artists"])
        ):
            match = result
            break
    if match:
        release_date = match["release_date"]
        release_month = datetime.strptime(release_date, "%Y-%m-%dT%H:%M:%S").strftime("%B %Y")
        release_months[(song["title"], song["artists"][0])] = release_month
    else:
        release_months[(song["title"], song["artists"][0])] = None  # Could not find

print(release_months)

